    {"name": "write", "arguments": {"path": "src/lib.rs", "overwrite": True, "content": "pub fn answer(command: &str) -> Option<i32> {\n    let command = command.strip_prefix(\"What is \")?.strip_suffix('?')?;\n    let words: Vec<&str> = command.split_whitespace().collect();\n    let mut index = 0;\n    let mut value = parse_number(words.get(index).copied()?)?;\n    index += 1;\n    while index < words.len() {\n        let (op, consumed) = match words[index] {\n            \"plus\" => (Op::Add, 1),\n            \"minus\" => (Op::Sub, 1),\n            \"multiplied\" if words.get(index + 1) == Some(&\"by\") => (Op::Mul, 2),\n            \"divided\" if words.get(index + 1) == Some(&\"by\") => (Op::Div, 2),\n            #[cfg(feature = \"exponentials\")]\n            \"raised\" if words.get(index + 1) == Some(&\"to\") && words.get(index + 2) == Some(&\"the\") && words.get(index + 3) == Some(&\"power\") && words.get(index + 4) == Some(&\"of\") => (Op::Pow, 5),\n            _ => return None,\n        };\n        index += consumed;\n        let rhs = parse_number(words.get(index).copied()?)?;\n        index += 1;\n        value = match op {\n            Op::Add => value.checked_add(rhs)?,\n            Op::Sub => value.checked_sub(rhs)?,\n            Op::Mul => value.checked_mul(rhs)?,\n            Op::Div => value.checked_div(rhs)?,\n            #[cfg(feature = \"exponentials\")]\n            Op::Pow => u32::try_from(rhs).ok().and_then(|n| value.checked_pow(n))?,\n        };\n    }\n    Some(value)\n}\n\n#[derive(Clone, Copy)]\nenum Op { Add, Sub, Mul, Div, #[cfg(feature = \"exponentials\")] Pow }\n\nfn parse_number(word: &str) -> Option<i32> {\n    if word.is_empty() || word == \"-\" || !word.bytes().enumerate().all(|(i, b)| b.is_ascii_digit() || (i == 0 && b == b'-')) {\n        return None;\n    }\n    word.parse().ok()\n}\n\n#[cfg(test)]\nmod tests {\n    use super::answer;\n\n    #[test]\n    fn arithmetic_is_evaluated_left_to_right() {\n        assert_eq!(answer(\"What is 5?\"), Some(5));\n        assert_eq!(answer(\"What is -7 plus 13 minus 2?\"), Some(4));\n        assert_eq!(answer(\"What is 3 plus 2 multiplied by 3?\"), Some(15));\n        assert_eq!(answer(\"What is 25 divided by 5?\"), Some(5));\n    }\n\n    #[test]\n    fn invalid_and_overflowing_questions_are_rejected() {\n        assert_eq!(answer(\"Who is the President?\"), None);\n        assert_eq!(answer(\"What is 1 plus plus 2?\"), None);\n        assert_eq!(answer(\"What is 52 cubed?\"), None);\n        assert_eq!(answer(\"What is 2147483647 plus 1?\"), None);\n        assert_eq!(answer(\"What is 1 divided by 0?\"), None);\n    }\n\n    #[cfg(feature = \"exponentials\")]\n    #[test]\n    fn exponentials() {\n        assert_eq!(answer(\"What is 2 raised to the power of 5?\"), Some(32));\n    }\n}\n"}},
